import { test, expect } from '@playwright/test';

test.describe('Context Menu on Table Row', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should display context menu on right-clicking a row', async ({ page }) => {
    const row = page.getByRole('row', { name: 'Row Name' }); // Replace 'Row Name' with the actual row name
    await row.dispatchEvent('contextmenu');

    const contextMenu = page.getByRole('menu');
    await expect(contextMenu).toBeVisible();
  });

  test('should have correct options in context menu', async ({ page }) => {
    const row = page.getByRole('row', { name: 'Row Name' }); // Replace 'Row Name' with the actual row name
    await row.dispatchEvent('contextmenu');

    const contextMenu = page.getByRole('menu');
    await expect(contextMenu.getByText('Edit')).toBeVisible();
    await expect(contextMenu.getByText('Delete')).toBeVisible();
  });
});
